SELECT row_number() OVER (ORDER BY ast30_corp_cd, ast30_cur_cd) AS key_id , f_cdnm('trCode', ast30_tr_cd, ast30_company_id, ast30_hold_date) AS tr_name , CASE WHEN ast30_tr_id IS NULL THEN '' ELSE '결산' END AS close_yn_name , CASE WHEN ast30_tr_id IS NULL THEN (ast30_for_fee - ast30_for_fix_fee) ELSE ( SELECT ast06_for_amt FROM ast06_tr WHERE ast06_tr_id = ast30_tr_id ) END AS for_ty_fee , CASE WHEN ast30_tr_id IS NULL THEN (ast30_fee - ast30_fix_fee) ELSE ( SELECT ast06_amt FROM ast06_tr WHERE ast06_tr_id = ast30_tr_id ) END AS ty_fee , t.ast30_company_id AS company_id , t.ast30_hold_date AS hold_date , t.ast30_corp_id AS corp_id , t.ast30_corp_cd AS corp_code , t.ast30_corp_nm AS corp_name , t.ast30_ast_class_tree_id AS ast_class_tree_id , t.ast30_cur_cd AS cur_code , t.ast30_fx_rate AS fx_rate , t.ast30_for_fee AS for_fee , t.ast30_fee AS fee , t.ast30_for_fix_fee AS for_fix_fee , t.ast30_fix_fee AS fix_fee , t.ast30_tr_id AS tr_id , t.ast30_tr_cd AS tr_code FROM ( SELECT ast30_company_id , ast30_hold_date , ast30_corp_id , sys15_corp_cd AS ast30_corp_cd , sys15_corp_nm AS ast30_corp_nm , ast30_ast_class_tree_id , ast30_cur_cd , ast30_fx_rate , SUM(ast30_for_fee) AS ast30_for_fee , SUM(ast30_fee) AS ast30_fee , SUM(ast30_for_fix_fee) AS ast30_for_fix_fee , SUM(ast30_fix_fee) AS ast30_fix_fee , ast31_tr_id AS ast30_tr_id , CASE ast01_item_s_class_cd WHEN '902013' THEN '9920' /* 9920:펀드사무관리보수 미수처리 */ WHEN '902001' THEN '9910' /* 9910:펀드운용보수 미수처리 */ ELSE NULL END AS ast30_tr_cd FROM ast30_book_fund_fee LEFT OUTER JOIN ast31_book_fund_fee_close ON ast31_book_fund_fee_id = ast30_book_fund_fee_id LEFT OUTER JOIN sys15_corp ON sys15_corp_id = ast30_corp_id INNER JOIN ast01_class_tree ON ast01_class_tree_id = ast30_ast_class_tree_id WHERE ast30_company_id = #{c.companyId} AND ast30_hold_date = #{c.holdDate}
AND ast30_corp_id||'' LIKE #{c.corpIdStr}
AND upper(concat(sys15_corp_cd,sys15_corp_nm,ast30_cur_cd)) LIKE '%'||upper(#{c.searchText})||'%'
GROUP BY ast30_company_id , ast30_hold_date , ast30_corp_id , sys15_corp_cd , sys15_corp_nm , ast30_ast_class_tree_id , ast30_cur_cd , ast30_fx_rate , ast31_tr_id , ast01_item_s_class_cd ) t

SELECT t.ast30_book_fund_fee_id AS book_fund_fee_id , t.ast30_fund_cd AS fund_code , t.ast30_fund_nm AS fund_name , CASE WHEN t.ast30_cur_cd = 'KRW' THEN null ELSE t.ast30_for_fee END AS for_fee , t.ast30_fee AS fee , t.ast30_for_ty_fee AS for_ty_fee , t.ast30_ty_fee AS ty_fee , t.ast30_for_fix_fee AS for_fix_fee , t.ast30_fix_fee AS fix_fee , t.ast30_fx_rate AS fx_rate FROM ( SELECT ast30_book_fund_fee.* , sys15_corp_cd AS ast30_corp_cd , sys15_corp_nm AS ast30_corp_nm , ast30_fee - COALESCE(ast30_fix_fee ,0) AS ast30_ty_fee , ast30_for_fee - COALESCE(ast30_for_fix_fee,0) AS ast30_for_ty_fee FROM ast30_book_fund_fee INNER JOIN sys15_corp ON sys15_corp_id = ast30_corp_id WHERE ast30_company_id = #{companyId} AND ast30_hold_date = #{holdDate} AND ast30_corp_id = #{corpId}
AND ast30_cur_cd = #{curCode}
) t WHERE upper(concat(ast30_corp_cd,ast30_corp_nm,ast30_fund_cd,ast30_fund_nm)) LIKE '%'||upper(#{searchText})||'%' ORDER BY ast30_fund_cd

