INSERT INTO ast32_book_fund_fee_recovery
SELECT f_create_seq()
     , ast30_book_fund_fee.*
  FROM ast30_book_fund_fee
 WHERE ast30_company_id         = #{companyId}
   AND ast30_hold_date          = #{holdDate}
   AND ast30_cur_cd             = #{curCode}
   AND ast30_ast_class_tree_id  = #{astClassTreeId}

       AND ast30_corp_id        = #{corpId}

mapper.update:
UPDATE ast30_book_fund_fee
   SET ast30_for_fix_fee = ast30_for_fee
     , ast30_fix_fee     = CASE WHEN ast30_cur_cd = 'KRW' THEN ast30_for_fee
                                ELSE trunc(ast30_for_fee * ast30_fx_rate) END
 WHERE ast30_company_id         = #{companyId}
   AND ast30_hold_date          = #{holdDate}
   AND ast30_cur_cd             = #{curCode}
   AND ast30_ast_class_tree_id  = #{astClassTreeId}

       AND ast30_corp_id        = #{corpId}

