UPDATE ast30_book_fund_fee
   SET ast30_fee     = #{r.fee}
     , ast30_for_fee = #{r.forFee}
     , ast30_fx_rate = #{r.fxRate}
 WHERE ast30_book_fund_fee_id = #{r.bookFundFeeId}
   AND ast30_company_id       = #{companyId}
